from workflow.compare_periodic_representations import activate_historical_source, load_fixture
activate_historical_source()
import numpy as np
from pyscf.pbc import df, gto, scf
from pyscf.pbc.tools.pbc import super_cell
f=load_fixture(); nmp=np.asarray(f['sampling_mesh']); nk=int(np.prod(nmp))
cell=gto.M(unit=f['unit'],a=np.asarray(f['lattice']),atom=[(s,tuple(x)) for s,x in f['atoms']],basis=f['basis'],pseudo=f['pseudopotential'],mesh=np.asarray(f['fft_mesh']),verbose=0)
kpts=cell.make_kpts(nmp,with_gamma_point=True)

def attach(mf, route, kpts_arg):
    if route == 'FFTDF':
        return mf
    if route == 'AFTDF':
        mf.with_df = df.AFTDF(mf.cell, kpts_arg)
        return mf
    if route == 'GDF':
        return mf.density_fit()
    if route == 'MDF':
        return mf.mix_density_fit()
    if route == 'RSGDF':
        return mf.rs_density_fit()
    raise ValueError(route)

for route in ('FFTDF','AFTDF','GDF','MDF','RSGDF'):
    kmf=attach(scf.KRHF(cell,kpts),route,kpts).set(conv_tol=1e-9,max_cycle=80)
    ek=kmf.kernel()
    scell=super_cell(cell,nmp)
    gmf=attach(scf.RHF(scell),route,np.zeros(3)).set(conv_tol=1e-9,max_cycle=80)
    eg=gmf.kernel()/nk
    print(route,'meshes',np.asarray(kmf.with_df.mesh).tolist() if kmf.with_df.mesh is not None else None,np.asarray(gmf.with_df.mesh).tolist() if gmf.with_df.mesh is not None else None,'energies',ek,eg,'delta',eg-ek,'converged',kmf.converged,gmf.converged,flush=True)
PY"

